// GENERATED by tools/t14-source-bake.py from the owner-supplied T-14 model.
// Do not hand-edit the encoded arrays. Donor tracks/wheels are intentionally
// absent; modern2.js retains the fleet-native animated seven-wheel system.
import * as THREE from 'three';

const DATA = {
  trackGuardL: { p: '', i: '' },
  trackGuardR: { p: '', i: '' },
  hull: { p: '', i: '' },
  hullDetail: { p: '', i: '' },
  turret: { p: '', i: '' },
  turretDetail: { p: '', i: '' },
  turretWeapon: { p: '', i: '' },
  gun: { p: '', i: '' },
};

const TURRET_PIVOT = [0.001, 1.836, -0.597];
const GUN_WORLD_PIVOT = [0.0, 2.03, 0.0];

function bytes(s) {
  const raw = atob(s);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}

function geometry(row) {
  if (!row.positions) {
    const pb = bytes(row.p), ib = bytes(row.i);
    row.positions = new Float32Array(
      pb.buffer, pb.byteOffset, pb.byteLength / 4);
    row.indices = new Uint32Array(
      ib.buffer, ib.byteOffset, ib.byteLength / 4);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(row.positions, 3));
  g.setIndex(new THREE.BufferAttribute(row.indices, 1));
  g.computeVertexNormals();
  const p = g.attributes.position, n = g.attributes.normal;
  const uv = new Float32Array(p.count * 2);
  for (let k = 0; k < p.count; k++) {
    const nx = Math.abs(n.getX(k)), ny = Math.abs(n.getY(k));
    const nz = Math.abs(n.getZ(k));
    let u, v;
    if (ny >= nx && ny >= nz) { u = p.getX(k); v = p.getZ(k); }
    else if (nx >= nz) { u = p.getZ(k); v = p.getY(k); }
    else { u = p.getX(k); v = p.getY(k); }
    uv[k * 2] = u * 0.35;
    uv[k * 2 + 1] = v * 0.35;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return g;
}

export function buildT14SourceGeometry(P) {
  P.turretG.position.fromArray(TURRET_PIVOT);
  P.gunG.position.set(
    GUN_WORLD_PIVOT[0] - TURRET_PIVOT[0],
    GUN_WORLD_PIVOT[1] - TURRET_PIVOT[1],
    GUN_WORLD_PIVOT[2] - TURRET_PIVOT[2],
  );
  P.add('hull', geometry(DATA.hull));
  P.add('hullDetail', geometry(DATA.hullDetail));
  P.add('hullTrackGuardL', geometry(DATA.trackGuardL));
  P.add('hullTrackGuardR', geometry(DATA.trackGuardR));
  // The owner source models the rear side cages as open presentation skins.
  // A real hull continues behind them; add a thin, fully enclosed backing
  // surface inside the existing cage envelope so top-down views cannot see
  // sky through the vehicle.  These remain hull-owned track-guard solids.
  P.add('hullTrackGuardL', new THREE.BoxGeometry(0.30, 0.035, 2.85),
    -1.79, 1.02, -2.18);
  P.add('hullTrackGuardR', new THREE.BoxGeometry(0.30, 0.035, 2.85),
    1.79, 1.02, -2.18);
  for (const side of [-1, 1]) {
    P.add('hullDetail', new THREE.BoxGeometry(0.26, 0.025, 0.24),
      side * 0.97, 1.50, -4.03);
    P.add(side < 0 ? 'hullTrackGuardL' : 'hullTrackGuardR',
      new THREE.BoxGeometry(0.22, 0.025, 0.20),
      side * 1.79, 1.02, -3.66);
  }
  P.add('turret', geometry(DATA.turret));
  P.add('turretDetail', geometry(DATA.turretDetail));
  P.add('turretDark', geometry(DATA.turretWeapon));
  P.add('gunDark', geometry(DATA.gun));

  // The source supplies its complete roof weapon assembly. Keep the fitting
  // census without drawing a second procedural gun.
  const mgMarker = new THREE.Group();
  mgMarker.name = 'fitting_t14SourceRoofWeapon';
  mgMarker.userData.fittingRoot = true;
  mgMarker.userData.fitting = 'pintleMG';
  P.turretG.add(mgMarker);
  P.muzzleZ = 6.45;
  P.topY = 1.93;
}
